<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Bursar'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired.');}
$id=filter_var($_POST['run_id']??null,FILTER_VALIDATE_INT);$action=(string)($_POST['action']??'');$ref=trim((string)($_POST['payment_reference']??''));if(!$id||!in_array($action,['Approve','MarkPaid','Void'],true)||strlen($ref)>120||($action==='MarkPaid'&&$ref==='')){$_SESSION['error']='Choose a valid payroll action. A payment reference is required when marking paid.';header('Location: ../?page=payroll&run='.(int)$id);exit;}
if($action==='Approve'&&!in_array($user['role'],['Administrator','Head'],true)){http_response_code(403);exit('Only school leadership can approve payroll.');}if($action==='MarkPaid'&&!in_array($user['role'],['Administrator','Bursar'],true)){http_response_code(403);exit('Only the administrator or bursar can record payroll payment.');}if($action==='Void'&&$user['role']!=='Administrator'){http_response_code(403);exit('Only the administrator can void a draft run.');}
$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT * FROM payroll_runs WHERE id=:id FOR UPDATE');$q->execute(['id'=>$id]);$r=$q->fetch();if(!$r)throw new DomainException('Payroll run not found.');if($action==='Approve'){if($r['status']!=='Draft')throw new DomainException('Only a draft run can be approved.');if((int)$r['created_by']===(int)$user['id'])throw new DomainException('The person who created the payroll run cannot approve it.');$q=$pdo->prepare("SELECT l.id,l.base_salary+COALESCE(SUM(CASE WHEN i.item_type='Earning' THEN i.amount WHEN i.item_type='Deduction' THEN -i.amount ELSE 0 END),0) AS net FROM payroll_lines l LEFT JOIN payroll_line_items i ON i.payroll_line_id=l.id WHERE l.run_id=:run GROUP BY l.id");$q->execute(['run'=>$id]);$netRows=$q->fetchAll();if(!$netRows)throw new DomainException('An empty payroll cannot be approved.');foreach($netRows as $line)if((float)$line['net']<0)throw new DomainException('A payroll line has deductions exceeding earnings; correct it before approval.');$q=$pdo->prepare("UPDATE payroll_runs SET status='Approved',approved_by=:user,approved_at=NOW() WHERE id=:id AND status='Draft'");$q->execute(['user'=>$user['id'],'id'=>$id]);$event='payroll.run_approved';}elseif($action==='MarkPaid'){if($r['status']!=='Approved')throw new DomainException('Only approved payroll can be marked paid.');if((int)$r['approved_by']===(int)$user['id'])throw new DomainException('The payroll approver cannot record payment for the same run.');$q=$pdo->prepare("UPDATE payroll_runs SET status='Paid',paid_by=:user,paid_at=NOW(),payment_reference=:ref WHERE id=:id AND status='Approved'");$q->execute(['user'=>$user['id'],'ref'=>$ref,'id'=>$id]);$event='payroll.run_paid';}else{if($r['status']!=='Draft')throw new DomainException('Only a draft payroll can be voided.');$q=$pdo->prepare("UPDATE payroll_runs SET status='Voided' WHERE id=:id AND status='Draft'");$q->execute(['id'=>$id]);$event='payroll.run_voided';}audit_log($event,'payroll_runs',(int)$id,['currency'=>$r['currency'],'period_start'=>$r['period_start']]);$pdo->commit();$_SESSION['notice']=$action==='MarkPaid'?'Payroll payment recorded.':'Payroll run updated.';}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();error_log('Payroll transition failed: '.$x->getMessage());$_SESSION['error']=$x instanceof DomainException?$x->getMessage():'Could not update payroll run.';}header('Location: ../?page=payroll&run='.(int)$id);exit;
